from boto3 import client


def fetch_document(document_id, config=None):
    config = config or {}
    dynamodb = client('dynamodb', region_name=config['region'])
    response = dynamodb.get_item(
        TableName=config['table_name'],
        Key={'id': {'S': document_id}}
    )
    item = response.get('Item', {})
    return {k: v[list(v.keys())[0]] for k, v in item.items()}

from boto3 import client


def query_documents(field_value, config=None):
    config = config or {}
    dynamodb = client('dynamodb', region_name=config['region'])
    response = dynamodb.query(
        TableName=config['table_name'],
        KeyConditionExpression='field_name = :value',
        ExpressionAttributeValues={':value': {'S': field_value}}
    )
    items = response.get('Items', [])
    return [{'id': item['id']['S'], 'document': item['document']['S']} for item in items]

from boto3 import client


def get_dynamodb_client(region):
    return client('dynamodb', region_name=region)

def normalize_payload(payload):
    return {'id': {'S': payload['id']}, 'document': {'S': payload['document']}}


def parse_response(response):
    return {k: v[list(v.keys())[0]] for k, v in response.items()}

import re


def check_text_safety(text):
    unsafe_patterns = [r'<script>', r'<img', r'<a']
    for pattern in unsafe_patterns:
        if re.search(pattern, text):
            return False
    return True
